@Test public void testRewrite() throws IOException { DefaultServer.setRootHandler( Handlers.predicates( PredicatedHandlersParser.parse( "path(/skipallrules) and true -> done
" + "method(GET) -> set(attribute='%{o,type}', value=get) 
" + "regex('(.*).css') -> {rewrite['${1}.xcss'];set(attribute='%{o,chained}', value=true)} 
" + "regex('(.*).redirect$') -> redirect['${1}.redirected']




" + "set[attribute='%{o,someHeader}', value=always]
" + "#ImJust a Comment
"+ "path-template('/foo/{bar}/{f}') -> set[attribute='%{o,template}', value='${bar}']
" + "path-template('/bar->foo') -> redirect(/);" + "regex('(.*).css') -> set[attribute='%{o,css}', value='true'] else set[attribute='%{o,css}', value='false']; " + "path(/restart) -> {rewrite(/foo/a/b); restart; }
" + "regex('^/path/([^/]+)/(.*)/?$') -> rewrite('/newpath'); set(attribute='%{o,result}', value='param1=$1&param2=$2'); done()", getClass().getClassLoader()), new HttpHandler() { @Override public void handleRequest(HttpServerExchange exchange) throws Exception { exchange.getResponseSender().send(exchange.getRelativePath()); } })); TestHttpClient client = new TestHttpClient(); try { HttpGet get = new HttpGet(DefaultServer.getDefaultServerURL() + "/foo/a/b"); HttpResponse result = client.execute(get); Assert.assertEquals(StatusCodes.OK, result.getStatusLine().getStatusCode()); String response = HttpClientUtils.readResponse(result); Assert.assertEquals("get", result.getHeaders("type")[0].getValue()); Assert.assertEquals("always", result.getHeaders("someHeader")[0].getValue()); Assert.assertEquals("a", result.getHeaders("template")[0].getValue()); Assert.assertEquals("false", result.getHeaders("css")[0].getValue()); Assert.assertEquals("/foo/a/b", response); get = new HttpGet(DefaultServer.getDefaultServerURL() + "/path/a/b"); result = client.execute(get); Assert.assertEquals(StatusCodes.OK, result.getStatusLine().getStatusCode()); response = HttpClientUtils.readResponse(result); Assert.assertEquals("param1=a&param2=b", result.getHeaders("result")[0].getValue()); Assert.assertEquals("/newpath", response); get = new HttpGet(DefaultServer.getDefaultServerURL() + "/foo/a/b.css"); result = client.execute(get); Assert.assertEquals(StatusCodes.OK, result.getStatusLine().getStatusCode()); response = HttpClientUtils.readResponse(result); Assert.assertEquals("get", result.getHeaders("type")[0].getValue()); Assert.assertEquals("true", result.getHeaders("chained")[0].getValue()); Assert.assertEquals("/foo/a/b.xcss", response); Assert.assertEquals("always", result.getHeaders("someHeader")[0].getValue()); Assert.assertEquals("true", result.getHeaders("css")[0].getValue()); Assert.assertEquals("a", result.getHeaders("template")[0].getValue()); get = new HttpGet(DefaultServer.getDefaultServerURL() + "/foo/a/b.redirect"); result = client.execute(get); Assert.assertEquals(StatusCodes.OK, result.getStatusLine().getStatusCode()); response = HttpClientUtils.readResponse(result); Assert.assertEquals("get", result.getHeaders("type")[0].getValue()); Assert.assertEquals("always", result.getHeaders("someHeader")[0].getValue()); Assert.assertEquals("a", result.getHeaders("template")[0].getValue()); Assert.assertEquals("/foo/a/b.redirected", response); get = new HttpGet(DefaultServer.getDefaultServerURL() + "/skipallrules"); result = client.execute(get); Assert.assertEquals(StatusCodes.OK, result.getStatusLine().getStatusCode()); response = HttpClientUtils.readResponse(result); Assert.assertEquals(0, result.getHeaders("someHeader").length); get = new HttpGet(DefaultServer.getDefaultServerURL() + "/restart"); result = client.execute(get); Assert.assertEquals(StatusCodes.OK, result.getStatusLine().getStatusCode()); response = HttpClientUtils.readResponse(result); Assert.assertEquals("get", result.getHeaders("type")[0].getValue()); Assert.assertEquals("always", result.getHeaders("someHeader")[0].getValue()); Assert.assertEquals("a", result.getHeaders("template")[0].getValue()); Assert.assertEquals("/foo/a/b", response); } finally { client.getConnectionManager().shutdown(); } }

