@Test public void testSameHttpStringReturned() throws BadRequestException { byte[] in = "GET http://www.somehost.net/somepath HTTP/1.1
Host: 	 www.somehost.net
Accept-Charset:	some
 	 value

".getBytes(); final ParseState context1 = new ParseState(10); HttpServerExchange result1 = new HttpServerExchange(null); HttpRequestParser.instance(OptionMap.EMPTY).handle(ByteBuffer.wrap(in), context1, result1); final ParseState context2 = new ParseState(10); HttpServerExchange result2 = new HttpServerExchange(null); HttpRequestParser.instance(OptionMap.EMPTY).handle(ByteBuffer.wrap(in), context2, result2); Assert.assertSame(result1.getProtocol(), result2.getProtocol()); Assert.assertSame(result1.getRequestMethod(), result2.getRequestMethod()); for (final HttpString header : result1.getRequestHeaders().getHeaderNames()) { boolean found = false; for (final HttpString header2 : result1.getRequestHeaders().getHeaderNames()) { if (header == header2) { found = true; break; } } if (header.equals(Headers.HOST)) { Assert.assertSame(Headers.HOST, header); } Assert.assertTrue("Could not found header " + header, found); } }

