@Test public void testSerialize() throws Exception { UriInfo uriInfo = createMock(UriInfo.class); Resource resource = createMock(Resource.class); Result result = new ResultImpl(true); result.setResultStatus(new ResultStatus(ResultStatus.STATUS.OK)); TreeNode<Resource> tree = result.getResultTree(); TreeNode<Resource> child = tree.addChild(resource, "resource1"); child.setProperty("href", "this is an href"); Map<String, Object> mapRootProps = new LinkedHashMap<>(); mapRootProps.put("prop2", "value2"); mapRootProps.put("prop1", "value1"); Map<String, Object> mapCategoryProps = new LinkedHashMap<>(); mapCategoryProps.put("catProp1", "catValue1"); mapCategoryProps.put("catProp2", "catValue2"); Map<String, Map<String, Object>> propertyMap = new LinkedHashMap<>(); propertyMap.put(null, mapRootProps); propertyMap.put("category", mapCategoryProps); expect(resource.getPropertiesMap()).andReturn(propertyMap).anyTimes(); expect(resource.getType()).andReturn(Resource.Type.Cluster).anyTimes(); replay(uriInfo, resource); Object o = new JsonSerializer().serialize(result).toString().replace("", ""); String expected = "{
" + " "href" : "this is an href",
" + " "prop2" : "value2",
" + " "prop1" : "value1",
" + " "category" : {
" + " "catProp1" : "catValue1",
" + " "catProp2" : "catValue2"
" + " }
" + "}"; assertEquals(expected, o); verify(uriInfo, resource); }

