@Test public void testMessageNull() throws RemotingException { mockChannel = mock(Channel.class); given(mockChannel.getAttribute("telnet.service")).willReturn(null); String result = invoke.telnet(mockChannel, null); assertEquals("Please input method name, eg: 
invoke xxxMethod(1234, "abcd", {"prop" : "value"})
invoke XxxService.xxxMethod(1234, "abcd", {"prop" : "value"})
invoke com.xxx.XxxService.xxxMethod(1234, "abcd", {"prop" : "value"})", result); }

@Test void testAvailable() throws IOException { final String s = "5
12345
0
"; final SessionInputBuffer inBuffer = new SessionInputBufferImpl(16); final ByteArrayInputStream inputStream = new ByteArrayInputStream(s.getBytes(StandardCharsets.US_ASCII)); try (ChunkedInputStream in = new ChunkedInputStream(inBuffer, inputStream)) { Assertions.assertEquals(0, in.available()); in.read(); Assertions.assertEquals(4, in.available()); } }

@Test void testChunkedInputStreamClose() throws IOException { final String s = "5
01234
5
56789
0
"; final SessionInputBuffer inBuffer = new SessionInputBufferImpl(16); final ByteArrayInputStream inputStream = new ByteArrayInputStream(s.getBytes(StandardCharsets.US_ASCII)); final ChunkedInputStream in = new ChunkedInputStream(inBuffer, inputStream); in.close(); in.close(); Assertions.assertThrows(StreamClosedException.class, () -> in.read()); final byte[] tmp = new byte[10]; Assertions.assertThrows(StreamClosedException.class, () -> in.read(tmp)); Assertions.assertThrows(StreamClosedException.class, () -> in.read(tmp, 0, tmp.length)); }

@Test void testChunkedInputStreamOneByteRead() throws IOException { final String s = "5
01234
5
56789
0
"; final SessionInputBuffer inBuffer = new SessionInputBufferImpl(16); final ByteArrayInputStream inputStream = new ByteArrayInputStream(s.getBytes(StandardCharsets.US_ASCII)); try (ChunkedInputStream in = new ChunkedInputStream(inBuffer, inputStream)) { int ch; int i = '0'; while ((ch = in.read()) != -1) { Assertions.assertEquals(i, ch); i++; } Assertions.assertEquals(-1, in.read()); Assertions.assertEquals(-1, in.read()); } }

@Test void testChunkedOutputStream() throws IOException { final SessionOutputBuffer outbuffer = new SessionOutputBufferImpl(16); final ByteArrayOutputStream outputStream = new ByteArrayOutputStream(); try (ChunkedOutputStream out = new ChunkedOutputStream(outbuffer, outputStream, 2)) { out.write('1'); out.write('2'); out.write('3'); out.write('4'); out.finish(); } final String content = new String(outputStream.toByteArray(), StandardCharsets.US_ASCII); Assertions.assertEquals("2
12
2
34
0

", content); }

@Test void testChunkedOutputStreamLargeChunk() throws IOException { final SessionOutputBuffer outbuffer = new SessionOutputBufferImpl(16); final ByteArrayOutputStream outputStream = new ByteArrayOutputStream(); try (ChunkedOutputStream out = new ChunkedOutputStream(outbuffer, outputStream, 2)) { out.write(new byte[] { '1', '2', '3', '4' }); out.finish(); } final String content = new String(outputStream.toByteArray(), StandardCharsets.US_ASCII); Assertions.assertEquals("4
1234
0

", content); }

@Test void testChunkedOutputStreamSmallChunk() throws IOException { final SessionOutputBuffer outbuffer = new SessionOutputBufferImpl(16); final ByteArrayOutputStream outputStream = new ByteArrayOutputStream(); try (ChunkedOutputStream out = new ChunkedOutputStream(outbuffer, outputStream, 2)) { out.write('1'); out.finish(); } final String content = new String(outputStream.toByteArray(), StandardCharsets.US_ASCII); Assertions.assertEquals("1
1
0

", content); }

@Test void testCorruptChunkedInputStreamInvalidFooter() throws IOException { final String s = "1
0
0
stuff
"; final SessionInputBuffer inBuffer = new SessionInputBufferImpl(16); final ByteArrayInputStream inputStream = new ByteArrayInputStream(s.getBytes(StandardCharsets.US_ASCII)); try (ChunkedInputStream in = new ChunkedInputStream(inBuffer, inputStream)) { in.read(); Assertions.assertThrows(MalformedChunkCodingException.class, in::read); } }

