56789
0
"; final SessionInputBuffer inBuffer = new SessionInputBufferImpl(16); final ByteArrayInputStream inputStream = new ByteArrayInputStream(s.getBytes(StandardCharsets.US_ASCII)); try (ChunkedInputStream in = new ChunkedInputStream(inBuffer, inputStream)) { Assertions.assertThrows(MalformedChunkCodingException.class, in::read); } }

@Test void testCorruptChunkedInputStreamMissingCRLF() throws IOException { final String s = "5
012345
56789
0
"; final SessionInputBuffer inBuffer = new SessionInputBufferImpl(16); final ByteArrayInputStream inputStream = new ByteArrayInputStream(s.getBytes(StandardCharsets.US_ASCII)); try (ChunkedInputStream in = new ChunkedInputStream(inBuffer, inputStream)) { final byte[] buffer = new byte[300]; final ByteArrayOutputStream out = new ByteArrayOutputStream(); Assertions.assertThrows(MalformedChunkCodingException.class, () -> { int len; while ((len = in.read(buffer)) > 0) { out.write(buffer, 0, len); } }); } }

