@Test void testMaxHeaderCount() { final String s = "header1: stuff
" + "header2: stuff 
" + "header3: stuff
" + "
"; final ByteArrayInputStream inputStream = new ByteArrayInputStream(s.getBytes(StandardCharsets.US_ASCII)); final SessionInputBuffer inBuffer = new SessionInputBufferImpl(16, StandardCharsets.US_ASCII.newDecoder()); Assertions.assertThrows(IOException.class, () -> AbstractMessageParser.parseHeaders(inBuffer, inputStream, 2, -1, null)); }

@Test void testMaxHeaderCountForFoldedHeader() { final String s = "header1: stuff
" + " stuff 
" + " stuff
" + "
"; final ByteArrayInputStream inputStream = new ByteArrayInputStream(s.getBytes(StandardCharsets.US_ASCII)); final SessionInputBuffer inBuffer = new SessionInputBufferImpl(16, StandardCharsets.US_ASCII.newDecoder()); Assertions.assertThrows(IOException.class, () -> AbstractMessageParser.parseHeaders(inBuffer, inputStream, 2, 15, null)); }

@Test void testBasicMessageParsing() throws Exception { final String s = "GET / HTTP/1.1
" + "Host: localhost
" + "User-Agent: whatever
" + "Cookie: c1=stuff
" + "
"; final ByteArrayInputStream inputStream = new ByteArrayInputStream(s.getBytes(StandardCharsets.US_ASCII)); final SessionInputBuffer inBuffer = new SessionInputBufferImpl(16, StandardCharsets.US_ASCII.newDecoder()); final DefaultHttpRequestParser parser = new DefaultHttpRequestParser(); final ClassicHttpRequest httprequest = parser.parse(inBuffer, inputStream); Assertions.assertEquals(Method.GET.name(), httprequest.getMethod()); Assertions.assertEquals("/", httprequest.getPath()); final Header[] headers = httprequest.getHeaders(); Assertions.assertEquals(3, headers.length); }

@Test void testMessageParsingTimeout() throws Exception { final String s = "GET \000/ HTTP/1.1\000
" + "Host: loca\000lhost
" + "User-Agent: whatever
" + "Coo\000kie: c1=stuff
" + "\000
"; final TimeoutByteArrayInputStream inputStream = new TimeoutByteArrayInputStream(s.getBytes(StandardCharsets.US_ASCII)); final SessionInputBuffer inBuffer = new SessionInputBufferImpl(16); final DefaultHttpRequestParser parser = new DefaultHttpRequestParser(); int timeoutCount = 0; ClassicHttpRequest httprequest = null; for (int i = 0; i < 10; i++) { try { httprequest = parser.parse(inBuffer, inputStream); break; } catch (final InterruptedIOException ex) { timeoutCount++; } } Assertions.assertNotNull(httprequest); Assertions.assertEquals(5, timeoutCount); Assertions.assertEquals(Method.GET.name(), httprequest.getMethod()); Assertions.assertEquals("/", httprequest.getPath()); final Header[] headers = httprequest.getHeaders(); Assertions.assertEquals(3, headers.length); }

@Test void testBasicMessageParsing() throws Exception { final String s = "HTTP/1.1 200 OK
" + "Server: whatever
" + "Date: some date
" + "Set-Cookie: c1=stuff
" + "
"; final ByteArrayInputStream inputStream = new ByteArrayInputStream(s.getBytes(StandardCharsets.US_ASCII)); final SessionInputBuffer inBuffer = new SessionInputBufferImpl(16, StandardCharsets.US_ASCII.newDecoder()); final DefaultHttpResponseParser parser = new DefaultHttpResponseParser(); final ClassicHttpResponse httpresponse = parser.parse(inBuffer, inputStream); Assertions.assertEquals(200, httpresponse.getCode()); Assertions.assertEquals("OK", httpresponse.getReasonPhrase()); final Header[] headers = httpresponse.getHeaders(); Assertions.assertEquals(3, headers.length); }

@Test void testMessageParsingTimeout() throws Exception { final String s = "HTTP\000/1.1 200\000 OK
" + "Server: wha\000tever
" + "Date: some date
" + "Set-Coo\000kie: c1=stuff
" + "\000
"; final TimeoutByteArrayInputStream inputStream = new TimeoutByteArrayInputStream(s.getBytes(StandardCharsets.US_ASCII)); final SessionInputBuffer inBuffer = new SessionInputBufferImpl(16); final DefaultHttpResponseParser parser = new DefaultHttpResponseParser(); int timeoutCount = 0; ClassicHttpResponse httpresponse = null; for (int i = 0; i < 10; i++) { try { httpresponse = parser.parse(inBuffer, inputStream); break; } catch (final InterruptedIOException ex) { timeoutCount++; } } Assertions.assertNotNull(httpresponse); Assertions.assertEquals(5, timeoutCount); Assertions.assertEquals(200, httpresponse.getCode()); Assertions.assertEquals("OK", httpresponse.getReasonPhrase()); final Header[] headers = httpresponse.getHeaders(); Assertions.assertEquals(3, headers.length); }

@Test void testReadingWitSmallBuffer() throws Exception { final String s = "10
1234567890123456
" + "40
12345678901234561234567890123456" + "12345678901234561234567890123456
0
"; final ReadableByteChannel channel = new ReadableByteChannelMock( new String[] {s}, StandardCharsets.US_ASCII); final SessionInputBuffer inbuf = new SessionInputBufferImpl(1024, 256, 0, StandardCharsets.US_ASCII); final BasicHttpTransportMetrics metrics = new BasicHttpTransportMetrics(); final ChunkDecoder decoder = new ChunkDecoder(channel, inbuf, metrics); final ByteBuffer dst = ByteBuffer.allocate(1024); final ByteBuffer tmp = ByteBuffer.allocate(10); int bytesRead = 0; while (dst.hasRemaining() && !decoder.isCompleted()) { final int i = decoder.read(tmp); if (i > 0) { bytesRead += i; tmp.flip(); dst.put(tmp); tmp.compact(); } } Assertions.assertEquals(80, bytesRead); Assertions.assertEquals("12345678901234561234567890123456" + "12345678901234561234567890123456" + "1234567890123456", CodecTestUtils.convert(dst)); Assertions.assertTrue(decoder.isCompleted()); }

@Test void testChunkNoExceed() throws Exception { final WritableByteChannelMock channel = new WritableByteChannelMock(64); final SessionOutputBuffer outbuf = new SessionOutputBufferImpl(1024, 16); final BasicHttpTransportMetrics metrics = new BasicHttpTransportMetrics(); final ChunkEncoder encoder = new ChunkEncoder(channel, outbuf, metrics); encoder.write(CodecTestUtils.wrap("1234")); encoder.complete(); outbuf.flush(channel); final String s = channel.dump(StandardCharsets.US_ASCII); Assertions.assertTrue(encoder.isCompleted()); Assertions.assertEquals("4
1234
0

", s); }

@Test void testReadLineChunks() throws Exception { final SessionInputBuffer inbuf = new SessionInputBufferImpl(16, 16); ReadableByteChannel channel = newChannel("One
Two
Three"); inbuf.fill(channel); final CharArrayBuffer line = new CharArrayBuffer(64); line.clear(); Assertions.assertTrue(inbuf.readLine(line, false)); Assertions.assertEquals("One", line.toString()); line.clear(); Assertions.assertTrue(inbuf.readLine(line, false)); Assertions.assertEquals("Two", line.toString()); line.clear(); Assertions.assertFalse(inbuf.readLine(line, false)); channel = newChannel("
Four"); inbuf.fill(channel); line.clear(); Assertions.assertTrue(inbuf.readLine(line, false)); Assertions.assertEquals("Three", line.toString()); inbuf.fill(channel); line.clear(); Assertions.assertTrue(inbuf.readLine(line, true)); Assertions.assertEquals("Four", line.toString()); line.clear(); Assertions.assertFalse(inbuf.readLine(line, true)); }

